-- Study Abroad country content, BATCH 17: Nigeria, Ghana, Kenya, Uganda, Tanzania.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('nigeria', 'ghana', 'kenya', 'uganda', 'tanzania'));
UPDATE countries SET why_title = 'Why study in Nigeria?', why_body = '<p>Nigeria has Africa''s largest population and a large university system, with federal and private universities offering English-medium degrees in medicine, engineering, law, business and the arts.</p><ul><li>English is the language of instruction</li><li>Large federal and private university system</li><li>Strong in medicine, law, engineering and creative industries</li><li>Lower costs than many destinations</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-ECOWAS applicants apply online for a student visa before travel. Sources disagree on the category label (STR or R7A), so confirm with the Nigeria Immigration Service or your nearest mission.</p><ul><li>Admission letter from a Nigerian institution</li><li>Minimum tuition payment before the visa application (one source)</li><li>Passport, photographs and proof of funds</li><li>Check the correct visa code with the embassy</li><li>ECOWAS citizens do not need a visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Nigeria Immigration Service and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most institutions take online applications, including the University of Ibadan and the University of Lagos.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance exam or direct entry requirements</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are set by each university and no national figure was found.</p><ul><li>One guide lists international undergraduate fees from NGN 0 to NGN 7,944,200 a year, which is too broad to rely on</li><li>Federal universities are generally cheaper than private universities</li><li>Living costs: highest in Lagos and Abuja</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof (IELTS or TOEFL) where required</li></ul>' WHERE slug = 'nigeria';
UPDATE countries SET why_title = 'Why study in Ghana?', why_body = '<p>Ghana is a stable, English-speaking West African country with well-regarded universities such as the University of Ghana and KNUST, strong in sciences, engineering, business and the arts.</p><ul><li>English-medium teaching</li><li>Stable democracy with a welcoming culture</li><li>KNUST and the University of Ghana are leading universities</li><li>Lower costs than many destinations</li></ul>', visa_title = 'Visa and residence permit', visa_body = '<p>Most non-ECOWAS students need a visa or ETA to enter, depending on nationality, and every international student must obtain a <strong>Residence Permit (Student)</strong> from the Ghana Immigration Service after arrival.</p><ul><li>University of Ghana lists a visa fee of US$75 for 3 months (a guide says about US$60; check the High Commission)</li><li>Visa documents: admission letter, proof of fee payment, passport and four photographs</li><li>Residence permit documents: introductory letter from the International Programmes Office, admission letter, Non-Citizen Ghana Card and proof of fee payment</li><li>Students are exempt from the bank statement requirement; GIS publishes no proof-of-funds amount</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ghana High Commission, GIS and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. The University of Ghana charges a non-refundable application processing fee of US$110.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>A confirmed 2026/27 University of Ghana tuition schedule was not found.</p><ul><li>KNUST first-year fees for international students: US$4,430-$7,563 (2026/27, provisional)</li><li>University of Ghana hostel (2025-26): US$2,146 for a single room, US$1,890 for a shared double</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'ghana';
UPDATE countries SET why_title = 'Why study in Kenya?', why_body = '<p>Kenya is East Africa''s education and business hub, with the University of Nairobi and other universities offering English-medium degrees in medicine, veterinary, business, agriculture and computing.</p><ul><li>English-medium teaching</li><li>Strong in agriculture, veterinary medicine and wildlife</li><li>Nairobi as a regional business and tech centre</li><li>Safari and outdoor opportunities</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>All international students need a <strong>Student''s Pass</strong>, applied for through the eFNS portal. A 2026 guide reports a fee of USD 100 a year for non-East Africans (an older partner page lists KES 5,000).</p><ul><li>Admission letter from a Kenyan institution</li><li>Passport, photographs and proof of funds</li><li>Medical insurance is advised on arrival</li><li>Any trade or employment, paid or not, is an offence on a Student''s Pass; internships need a separate pass</li><li>No post-study work route is found; later jobs need a work permit</li><li>EAC citizens may be exempt from the pass fee</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Kenya Department of Immigration (eFNS) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof (IELTS, TOEFL or Duolingo)</li><li>KCSE equivalent or A-levels</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>One site lists international Bachelor''s tuition at about KES 15,000-17,143 a year, which looks implausibly low</li><li>Studyportals lists veterinary medicine at about KES 468,000 a year for non-residents</li><li>Check the University of Nairobi fee schedule</li><li>Living costs: about US$300-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> KCSE or an equivalent (A-levels, IB) with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS or TOEFL for non-native speakers</li></ul>' WHERE slug = 'kenya';
UPDATE countries SET why_title = 'Why study in Uganda?', why_body = '<p>Uganda is home to Makerere University, one of Africa''s oldest, with English-medium degrees in medicine, veterinary, agriculture, tourism and the sciences.</p><ul><li>English-medium teaching</li><li>Makerere is a leading African research university</li><li>Strong in medicine, veterinary, wildlife and agriculture</li><li>Low cost of living</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>This search found no official guidance on the Uganda student pass, so confirm the 2026 steps with the Directorate of Citizenship and Immigration Control and your university.</p><ul><li>Admission letter from a Ugandan institution</li><li>Passport and photographs</li><li>Insurance certificate from a reputable insurer at admission (Makerere listing)</li><li>Check the current student pass fee and procedure with the immigration directorate</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Uganda immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Makerere runs graduate admission through its 2026/27 advert and online portal.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Motivation letter for postgraduate programmes</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Makerere lists international graduate fees roughly 60% above Ugandan and East African rates.</p><ul><li>Example: MSc Crop Science for 2026/27 is UGX 8,000,000 for international students against UGX 5,000,000 for others (excludes functional fees, accommodation and books)</li><li>Bachelor''s: Studyportals lists UGX 2,874,454 a semester for Computer Science (unconfirmed)</li><li>Living costs: about US$200-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> UACE or an equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'uganda';
UPDATE countries SET why_title = 'Why study in Tanzania?', why_body = '<p>Tanzania offers English-medium degrees at the University of Dar es Salaam and other universities, with strengths in wildlife, tourism, agriculture and Swahili language and culture.</p><ul><li>English as the language of instruction at UDSM</li><li>Strong in wildlife, tourism, agriculture and engineering</li><li>Kilimanjaro, Serengeti and Zanzibar</li><li>Swahili language and culture immersion</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>Every international student needs a <strong>Student Pass</strong>. UDSM puts the fee at US$250 (a guide says US$200 for Student Pass I), and East African Community students apply for a free exemption certificate.</p><ul><li>Admission letter and certified academic transcripts</li><li>Certificate of registration of the institution, proof of sponsorship and joining instructions</li><li>Apply through the e-Immigration portal</li><li>Students have no work rights; academic internships may be allowed</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Tanzania Immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Foreign applicants apply directly to each university. UDSM postgraduate applications run through admission.udsm.ac.tz.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li><li>Entrance requirements per programme</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UDSM lists higher fees for non-Tanzanians.</p><ul><li>2025/26 bachelor joining instructions: TZS 5,250,000 for non-Tanzanians against TZS 1,000,000 for Tanzanians (BA History example)</li><li>2026/27 postgraduate: TZS 15,075,000 for an 18-month MSc in engineering for students from outside Africa, plus an international student levy of TZS 750,000 a year (TZS 1,000,000 for PhD)</li><li>A third-party site lists about US$3,060, which does not match the official figures</li><li>Living costs: about US$250-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> ACSEE or an equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'tanzania';
COMMIT;
